// WLC price feed: official UK fuel and electricity prices -> covase_config 'wlc_settings'.
// Fuel: GOV.UK "Weekly road fuel prices" (DESNZ), latest row of the CSV, found via the
// GOV.UK content API so the weekly-changing file link never needs updating.
// Electricity: Ofgem price-cap page, the electricity unit rate in pence per kWh.
// Every figure is range-checked; anything that fails is not written, and an alert goes
// to admin@ instead. Prices that did pass are still written.
const http = (o) => this.helpers.httpRequest(Object.assign({ timeout: 20000, headers: { 'User-Agent': 'Covase ORBIS price feed (admin@covase.co.uk)' } }, o));
const SB = $vars.SUPABASE_URL, KEY = $vars.SUPABASE_ANON_KEY;
const sbHead = { apikey: KEY, Authorization: 'Bearer ' + KEY, 'Content-Type': 'application/json' };
const iso = (d) => d.toISOString().slice(0, 10);
const out = { ran_at: new Date().toISOString(), fuel: null, elec: null, problems: [] };

// ── Fuel (GOV.UK) ──
try {
  const page = await http({ url: 'https://www.gov.uk/api/content/government/statistics/weekly-road-fuel-prices', json: true });
  const atts = [];
  const walk = (x) => { if (!x || typeof x !== 'object') return; if (Array.isArray(x)) return x.forEach(walk); if (typeof x.url === 'string' && /\.csv(\?|$)/i.test(x.url)) atts.push(x); Object.values(x).forEach(walk); };
  walk(page);
  if (!atts.length) throw new Error('no CSV attached to the GOV.UK weekly road fuel prices page');
  const csvUrl = atts[0].url.startsWith('http') ? atts[0].url : 'https://www.gov.uk' + atts[0].url;
  const csv = String(await http({ url: csvUrl }));
  const rows = csv.split(/\r?\n/).map(l => { const r = []; let c = '', q = false; for (const ch of l) { if (ch === '"') q = !q; else if (ch === ',' && !q) { r.push(c.trim()); c = ''; } else c += ch; } r.push(c.trim()); return r; });
  const h = rows.findIndex(r => r.some(x => /ULSP/i.test(x)) && r.some(x => /ULSD/i.test(x)));
  if (h < 0) throw new Error('fuel CSV has no ULSP/ULSD heading');
  const hdr = rows[h];
  const col = (fuel) => hdr.findIndex(x => new RegExp(fuel, 'i').test(x) && /pump\s*price/i.test(x));
  const ip = col('ULSP'), id = col('ULSD'), idate = hdr.findIndex(x => /date/i.test(x));
  if (ip < 0 || id < 0) throw new Error('fuel CSV has no pump price columns');
  const data = rows.slice(h + 1).filter(r => parseFloat(r[ip]) > 0 && parseFloat(r[id]) > 0);
  if (!data.length) throw new Error('fuel CSV has no price rows');
  const last = data[data.length - 1];
  const petrol = parseFloat(last[ip]) / 100, diesel = parseFloat(last[id]) / 100; // p/litre -> £/litre
  if (!(petrol > 1 && petrol < 2.5) || !(diesel > 1 && diesel < 2.5)) throw new Error(`fuel prices out of range (petrol ${petrol}, diesel ${diesel})`);
  let asOf = iso(new Date());
  const ds = idate >= 0 ? last[idate] : '';
  let m = ds.match(/^(\d{1,2})\/(\d{1,2})\/(\d{4})/); if (m) asOf = `${m[3]}-${m[2].padStart(2, '0')}-${m[1].padStart(2, '0')}`;
  else if ((m = ds.match(/^(\d{4})-(\d{2})-(\d{2})/))) asOf = m[0];
  else if (ds && !isNaN(Date.parse(ds))) asOf = iso(new Date(Date.parse(ds)));
  if ((Date.now() - Date.parse(asOf)) / 864e5 > 21) throw new Error(`newest GOV.UK figure is from ${asOf} — over three weeks old, so not used`);
  out.fuel = { petrol_litre: Math.round(petrol * 10000) / 10000, diesel_litre: Math.round(diesel * 10000) / 10000, as_of: asOf, source: csvUrl };
} catch (e) { out.problems.push('Fuel: ' + e.message); }

// ── Electricity (Ofgem price cap) ──
try {
  const html = String(await http({ url: 'https://www.ofgem.gov.uk/information-consumers/energy-advice-households/energy-price-cap' }));
  const text = html.replace(/<script[\s\S]*?<\/script>|<style[\s\S]*?<\/style>/gi, ' ').replace(/<[^>]+>/g, ' ').replace(/&nbsp;/g, ' ').replace(/\s+/g, ' ');
  const i = text.search(/electricity/i);
  if (i < 0) throw new Error('Ofgem page has no electricity section');
  const m = text.slice(i).match(/(\d{1,2}\.\d{1,2})\s*(?:p|pence)\s*(?:per|\/)\s*kWh/i);
  if (!m) throw new Error('no "pence per kWh" figure after the electricity heading on the Ofgem page');
  const kwh = parseFloat(m[1]) / 100;
  if (!(kwh > 0.12 && kwh < 0.6)) throw new Error(`electricity price out of range (${kwh})`);
  out.elec = { elec_kwh: Math.round(kwh * 10000) / 10000, as_of: iso(new Date()), source: 'https://www.ofgem.gov.uk/information-consumers/energy-advice-households/energy-price-cap' };
} catch (e) { out.problems.push('Electricity: ' + e.message); }

// ── Save: read-modify-write so tax tables, rates and battery rules are untouched ──
const cur = await http({ url: `${SB}/rest/v1/covase_config?key=eq.wlc_settings&select=value`, headers: sbHead, json: true });
const value = (Array.isArray(cur) && cur[0] && cur[0].value) || {};
if (out.fuel) Object.assign(value, { petrol_litre: out.fuel.petrol_litre, diesel_litre: out.fuel.diesel_litre, fuel_as_of: out.fuel.as_of });
if (out.elec) Object.assign(value, { elec_kwh: out.elec.elec_kwh, elec_as_of: out.elec.as_of });
value.price_feed = { ran_at: out.ran_at, fuel_source: out.fuel && out.fuel.source, elec_source: out.elec && out.elec.source, problems: out.problems };
await http({ method: 'POST', url: `${SB}/rest/v1/covase_config`, headers: Object.assign({ Prefer: 'resolution=merge-duplicates,return=minimal' }, sbHead), body: { key: 'wlc_settings', value, updated_at: out.ran_at }, json: true });

// ── Alert admin@ if anything failed (reuses the proven Graph sender) ──
if (out.problems.length) {
  try {
    await http({ method: 'POST', url: 'https://covase.app.n8n.cloud/webhook/covase-supplier-booking-request', json: true, body: {
      to: 'admin@covase.co.uk', from: 'rentals@covase.co.uk', customer: 'ORBIS price feed',
      subject: 'ORBIS choice lists: price update needs a look',
      bodyHtml: '<p>The weekly fuel/electricity price update could not fill everything in. Anything listed below kept its old price — please type the current figure in Choice lists → ⚙ Tax tables.</p><ul>' + out.problems.map(p => '<li>' + p.replace(/</g, '&lt;') + '</li>').join('') + '</ul>' } });
  } catch (e) { out.problems.push('Alert email failed: ' + e.message); }
}
return [{ json: { ok: !out.problems.length, fuel: out.fuel, electricity: out.elec, problems: out.problems } }];
